/**
 * Client for versioned Cursor-managed store operations.
 *
 * This module owns transport, envelope encoding, response validation, typed
 * errors, and bounded retries. Availability requires both a compatible
 * transport and a managed store, resolved lazily for each call.
 */
import { MEMORY_APPEND_MAX_RECORD_BYTES, memoryAppendResponseSchema, memoryReadResponseSchema, STORE_API_MEMORY_APPEND_CALL, STORE_API_MEMORY_READ_CALL, STORE_API_PATH, STORE_API_PROTOCOL_VERSION, serializedRecordBytes, } from "../store-api-protocol.js";
import { resolveCursorApiBaseUrl, resolveCursorApiFetch, resolveCursorApiKey, } from "./cursor-api-transport.js";
import { resolveDeploymentStoreSourceIdSync, resolveStoreProtocolSync, storeProtocolEnablesStoreApi, } from "./hosted-store-secrets.js";
import { isRecord } from "../is-record.js";
export class StoreApiCallError extends Error {
    constructor(kind, message, status) {
        super(message);
        this.kind = kind;
        this.status = status;
        this.name = "StoreApiCallError";
    }
}
/**
 * Bounded backoff policy. Domain calls run at turn boundaries (a memory
 * append after `turn.completed`), so the budget is a few short retries, not
 * persistence: 3 attempts total and never more than 2s asleep between them.
 * A 429 whose Retry-After exceeds the cap gives up immediately.
 */
const STORE_API_MAX_ATTEMPTS = 3;
const STORE_API_MAX_BACKOFF_MS = 2_000;
/**
 * Hard deadline per request. Hydration runs at the head of the session
 * dispatch chain, so a stalled connection must not delay every queued
 * handler.
 */
const STORE_API_FETCH_TIMEOUT_MS = 15_000;
function backoffMs(attempt, random) {
    return Math.min(200 * 2 ** attempt * (0.5 + random()), STORE_API_MAX_BACKOFF_MS);
}
/** True when managed store operations are available. */
export function isStoreApiLaneEnabled(options = {}) {
    const protocol = options.resolveStoreProtocol?.() ?? resolveStoreProtocolSync();
    if (!storeProtocolEnablesStoreApi(protocol)) {
        return false;
    }
    const sourceId = (options.resolveStoreSourceId?.() ??
        options.storeSourceId ??
        resolveDeploymentStoreSourceIdSync())?.trim();
    return sourceId !== undefined && sourceId !== "";
}
export function createStoreApiClient(options = {}) {
    const sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
    const random = options.random ?? Math.random;
    /** One POST of a versioned envelope; returns the parsed 2xx body. */
    const postOnce = async (call, envelope) => {
        const fetchImpl = resolveCursorApiFetch(options);
        return await fetchImpl(`${resolveCursorApiBaseUrl(options)}${STORE_API_PATH}/${call}`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${resolveCursorApiKey(options)}`,
                "Content-Type": "application/json",
            },
            body: JSON.stringify(envelope),
            signal: AbortSignal.timeout(STORE_API_FETCH_TIMEOUT_MS),
        });
    };
    /** The response's `Retry-After` in ms, when present and numeric. */
    const retryAfterDelayMs = (response) => {
        const header = response.headers.get("retry-after")?.trim();
        const seconds = header === undefined || header === "" ? Number.NaN : Number(header);
        return Number.isFinite(seconds) ? seconds * 1_000 : undefined;
    };
    const describeErrorBody = async (response) => {
        try {
            const parsed = await response.json();
            if (isRecord(parsed) && typeof parsed.error === "string") {
                return parsed.error;
            }
        }
        catch {
            // Non-JSON error body; the status is the message.
        }
        return `HTTP ${response.status}`;
    };
    const callApi = async (call, envelope) => {
        let lastFailure;
        // A shed's Retry-After (when within the cap) overrides the next jittered
        // backoff; cleared before every attempt.
        let nextDelayMs;
        for (let attempt = 0; attempt < STORE_API_MAX_ATTEMPTS; attempt += 1) {
            if (attempt > 0) {
                await sleep(nextDelayMs ?? backoffMs(attempt, random));
            }
            nextDelayMs = undefined;
            let response;
            try {
                response = await postOnce(call, envelope);
            }
            catch (error) {
                lastFailure = new StoreApiCallError("unavailable", `store api ${call} transport failure: ${error instanceof Error ? error.message : String(error)}`);
                continue;
            }
            if (response.ok) {
                try {
                    return (await response.json());
                }
                catch {
                    throw new StoreApiCallError("bad_response", `store api ${call} answered non-JSON (${response.status})`, response.status);
                }
            }
            if (response.status === 429) {
                const retryDelayMs = retryAfterDelayMs(response);
                const shed = new StoreApiCallError("shed", `store api ${call} shed: ${await describeErrorBody(response)}`, response.status);
                if (retryDelayMs !== undefined && retryDelayMs > STORE_API_MAX_BACKOFF_MS) {
                    // A long Retry-After is an explicit instruction to stop retrying.
                    throw shed;
                }
                nextDelayMs = retryDelayMs;
                lastFailure = shed;
                continue;
            }
            if (response.status >= 500) {
                // A degraded 503 can carry `Retry-After`. Honor it clamped to the
                // backoff cap. Unlike a shed, a
                // 5xx is transient by definition, so a long hint never means "give
                // up", just "wait the cap".
                const retryDelayMs = retryAfterDelayMs(response);
                if (retryDelayMs !== undefined) {
                    nextDelayMs = Math.min(retryDelayMs, STORE_API_MAX_BACKOFF_MS);
                }
                lastFailure = new StoreApiCallError("unavailable", `store api ${call} failed: ${await describeErrorBody(response)}`, response.status);
                continue;
            }
            // Any other 4xx is deterministic; retrying re-sends the same refusal.
            throw new StoreApiCallError("rejected", `store api ${call} rejected: ${await describeErrorBody(response)}`, response.status);
        }
        throw lastFailure ?? new StoreApiCallError("unavailable", "no attempt ran");
    };
    return {
        async memoryAppend(payload) {
            const recordBytes = serializedRecordBytes(payload.record);
            if (recordBytes > MEMORY_APPEND_MAX_RECORD_BYTES) {
                // The server-side controller enforces the same cap; checking here
                // spares a doomed request and fails with the same typed shape.
                throw new StoreApiCallError("rejected", `memory.append record is ${recordBytes} serialized bytes; the cap is ${MEMORY_APPEND_MAX_RECORD_BYTES}`);
            }
            const body = await callApi(STORE_API_MEMORY_APPEND_CALL, {
                v: STORE_API_PROTOCOL_VERSION,
                call: STORE_API_MEMORY_APPEND_CALL,
                payload,
            });
            if (!memoryAppendResponseSchema.safeParse(body).success) {
                throw new StoreApiCallError("bad_response", "unexpected memory.append response shape");
            }
        },
        async memoryReadContent(payload) {
            const body = await callApi(STORE_API_MEMORY_READ_CALL, {
                v: STORE_API_PROTOCOL_VERSION,
                call: STORE_API_MEMORY_READ_CALL,
                payload,
            });
            const parsed = memoryReadResponseSchema.safeParse(body);
            if (!parsed.success) {
                throw new StoreApiCallError("bad_response", "unexpected memory.read response shape");
            }
            if (parsed.data.journal === null) {
                return undefined;
            }
            // Fetch bulk bytes from the authorized URL. This read is not retried;
            // the whole operation runs again at the next session start.
            const fetchImpl = resolveCursorApiFetch(options);
            let response;
            try {
                response = await fetchImpl(parsed.data.journal.url, {
                    method: "GET",
                    redirect: "manual",
                    signal: AbortSignal.timeout(STORE_API_FETCH_TIMEOUT_MS),
                });
            }
            catch (error) {
                throw new StoreApiCallError("unavailable", `memory.read journal fetch transport failure: ${error instanceof Error ? error.message : String(error)}`);
            }
            if (response.status === 404) {
                // The snapshot raced a rotation or delete; absent is absent.
                return undefined;
            }
            if (!response.ok) {
                throw new StoreApiCallError("unavailable", `memory.read journal fetch failed (HTTP ${response.status})`, response.status);
            }
            return new Uint8Array(await response.arrayBuffer());
        },
    };
}
